def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        safe = DAILY_SALARY * 0.25
        if hp <= 2 or no_water_days >= 1:
            safe = DAILY_SALARY * 0.6
        return max(0, min(budget, safe))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    total_players = 1 + len(alive)

    for opp in alive:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    units = supply / float(WATER_REQ)
    scarcity = units < total_players

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = DAILY_SALARY * 0.5
        avg_prev = DAILY_SALARY * 0.45

    if hp <= 1 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2)
    elif hp <= 2 or no_water_days >= 1:
        if scarcity:
            bid = max(DAILY_SALARY * 0.82, highest_prev + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.68, avg_prev + 1)
    else:
        if scarcity:
            bid = max(DAILY_SALARY * 0.58, avg_prev + 1)
            if highest_prev >= DAILY_SALARY * 0.85:
                bid = DAILY_SALARY * 0.34
            elif desperate_count >= 2:
                bid = max(bid, DAILY_SALARY * 0.7)
        else:
            bid = DAILY_SALARY * 0.38
            if highest_prev < DAILY_SALARY * 0.45:
                bid = max(bid, highest_prev + 0.75)

    if rich_count >= max(1, len(alive) // 2) and scarcity:
        bid += 2.0

    if day >= 8 and hp <= 3:
        bid = max(bid, DAILY_SALARY * 0.8)

    reserve_floor = 0
    if hp >= 4 and no_water_days == 0:
        reserve_floor = budget * 0.55
        bid = min(bid, max(0, budget - reserve_floor))

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    max_bid = min(budget, DAILY_SALARY * 0.9)

    if hp <= 2 or no_water_days >= 1:
        bid = min(budget, DAILY_SALARY * 0.95)
    else:
        scarcity_factor = max(0.5, 1.0 - (supply - WATER_REQ) / (2.0 * WATER_REQ))
        bid = DAILY_SALARY * scarcity_factor
        if bid > max_bid:
            bid = max_bid
