def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from traces (immediate reaction only)
    yesterday_bids = []
    yesterday_pressures = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            yesterday_bids.append(b)
        # If they were already in trouble, treat as higher urgency
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            yesterday_pressures.append(1)

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    urgency = sum(yesterday_pressures)

    # Supply pressure: lower supply -> more competitive bidding
    # Normalize around [MIN_SUPPLY, MAX_SUPPLY]
    if MAX_SUPPLY - MIN_SUPPLY <= 0:
        supply_factor = 0.5
    else:
        supply_factor = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # Decide bid target
    # If opponents bid high yesterday, they likely anticipate scarcity today.
    # We slightly outbid to secure water, but cap to avoid bankruptcy.
    if highest_prev_bid >= DAILY_SALARY * 0.85 or urgency >= 2:
        # More aggressive when supply is not abundant
        scarcity_boost = 0.65 + (1.0 - supply_factor) * 0.35
        target = DAILY_SALARY * 0.45 * scarcity_boost + (highest_prev_bid * 0.15)
    else:
        # Conservative baseline; bid more only if our hp/no_water_days are critical
        critical = (my_status.get('hp', 0) <= 2) or (my_status.get('no_water_days', 0) >= 2)
        if critical:
            target = DAILY_SALARY * (0.75 - supply_factor * 0.1)
        else:
            target = DAILY_SALARY * (0.55 - supply_factor * 0.05)

    # Ensure we don't exceed what we can pay
    budget_cap = float(my_status.get('budget', 0.0))
    if budget_cap <= 0:
        return 0.0

    bid = min(budget_cap, target)

    # Discretize slightly to reduce overfitting to float bids
    # (still valid as float; keep simple)
    return float(max(0.0, bid))
